<?php
namespace App\Services;
use App\Models\BiometricDevice; use App\Models\BiometricEmployeeMapping; use App\Models\BiometricEvent; use Carbon\Carbon; use Illuminate\Support\Facades\DB; use RuntimeException;
class BiometricIngestService
{
public function ingest(BiometricDevice $device,string $token,array $payload):BiometricEvent{if(!$device->active||!hash_equals($device->token_hash,hash('sha256',$token)))throw new RuntimeException('Invalid biometric device credentials.');foreach(['event_id','employee_id','event_type','event_at'] as $key)if(blank($payload[$key]??null))throw new RuntimeException("Missing biometric field: {$key}");$type=strtolower((string)$payload['event_type']);if(!in_array($type,['in','out'],true))throw new RuntimeException('event_type must be in or out.');$hash=hash('sha256',json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return DB::transaction(function()use($device,$payload,$type,$hash){$existing=BiometricEvent::where('biometric_device_id',$device->id)->where('external_event_id',(string)$payload['event_id'])->lockForUpdate()->first();if($existing)return $existing;$mapping=BiometricEmployeeMapping::with('employee')->where('biometric_device_id',$device->id)->where('external_employee_id',(string)$payload['employee_id'])->first();if(!$mapping)throw new RuntimeException('Unknown biometric employee mapping.');$at=$this->eventTime((string)$payload['event_at'],$device->timezone);$event=BiometricEvent::create(['biometric_device_id'=>$device->id,'external_event_id'=>(string)$payload['event_id'],'external_employee_id'=>(string)$payload['employee_id'],'event_type'=>$type,'event_at'=>$at,'payload_hash'=>$hash]);try{$attendance=app(AttendanceService::class)->recordPunch($mapping->employee,$type,$at,'biometric');$event->update(['attendance_entry_id'=>$attendance->id,'processed_at'=>now()]);$device->update(['last_seen_at'=>now()]);}catch(\Throwable $e){$event->update(['error'=>mb_substr($e->getMessage(),0,2000)]);throw $e;}return $event->refresh();});}
private function eventTime(string $value,string $timezone):Carbon{$hasOffset=(bool)preg_match('/(?:Z|[+\-]\d{2}:?\d{2})$/i',$value);$at=Carbon::parse($value,$hasOffset?null:$timezone);return $at->setTimezone(config('app.timezone','Asia/Amman'));}
}
